void compatTraceInstall(HMODULE module){
 if(!module)return;auto* base=reinterpret_cast<BYTE*>(module);auto* dos=reinterpret_cast<IMAGE_DOS_HEADER*>(base);if(dos->e_magic!=IMAGE_DOS_SIGNATURE)return;auto* nt=reinterpret_cast<IMAGE_NT_HEADERS*>(base+dos->e_lfanew);auto dir=nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT];if(!dir.VirtualAddress)return;
 Hook hooks[]{{"GetKeyboardState",reinterpret_cast<void*>(getKeyboard)},{"GetAsyncKeyState",reinterpret_cast<void*>(getAsync)},{"GetKeyState",reinterpret_cast<void*>(getKey)},{"RegisterRawInputDevices",reinterpret_cast<void*>(regRaw)},{"GetRawInputData",reinterpret_cast<void*>(readRaw)},{"SetCapture",reinterpret_cast<void*>(setCapture)},{"ClipCursor",reinterpret_cast<void*>(clipCursor)},{"SetCursorPos",reinterpret_cast<void*>(setCursor)},{"DispatchMessageW",reinterpret_cast<void*>(dispatch<true>)},{"DispatchMessageA",reinterpret_cast<void*>(dispatch<false>)}};
 for(auto* d=reinterpret_cast<IMAGE_IMPORT_DESCRIPTOR*>(base+dir.VirtualAddress);d->Name;++d){if(!d->OriginalFirstThunk)continue;auto* names=reinterpret_cast<IMAGE_THUNK_DATA*>(base+d->OriginalFirstThunk);auto* slots=reinterpret_cast<IMAGE_THUNK_DATA*>(base+d->FirstThunk);for(;names->u1.AddressOfData;++names,++slots){if(IMAGE_SNAP_BY_ORDINAL(names->u1.Ordinal))continue;auto* name=reinterpret_cast<IMAGE_IMPORT_BY_NAME*>(base+names->u1.AddressOfData);for(auto& h:hooks)if(!strcmp(reinterpret_cast<char*>(name->Name),h.name)){DWORD old;if(VirtualProtect(&slots->u1.Function,sizeof(ULONG_PTR),PAGE_READWRITE,&old)){InterlockedExchangePointer(reinterpret_cast<void*volatile*>(&slots->u1.Function),h.address);VirtualProtect(&slots->u1.Function,sizeof(ULONG_PTR),old,&old);}}}}
}
void compatTraceWrite(const char* path,const char* mode,unsigned long long polls,unsigned long long virtualEvents){if(!path||!*path)return;FILE*f=fopen(path,"wb");if(!f)return;fprintf(f,"{\"mode\":\"%s\",\"pid\":%lu,\"polls\":%llu,\"virtualEvents\":%llu,\"GetKeyboardState\":%llu,\"GetAsyncKeyState\":%llu,\"GetKeyState\":%llu,\"RegisterRawInputDevices\":%llu,\"GetRawInputData\":%llu,\"SetCapture\":%llu,\"ClipCursor\":%llu,\"SetCursorPos\":%llu,\"messages\":%llu,\"keyMessages\":%llu,\"mouseMessages\":%llu,\"rawMessages\":%llu,\"dinput8Loaded\":%d}\n",mode,GetCurrentProcessId(),polls,virtualEvents,keyboard.load(),asyncKey.load(),key.load(),rawRegister.load(),rawRead.load(),capture.load(),clip.load(),warp.load(),messages.load(),keyMessages.load(),mouseMessages.load(),rawMessages.load(),GetModuleHandleW(L"dinput8.dll")!=nullptr);fclose(f);}